// One-off script — removes the two throwaway QA student accounts created to
// verify the Appréciation/Conduite module in production, plus their
// associated test data (StudentAppreciation row, Notification, and the
// AuditLog entries generated by creating that appreciation). Scoped to
// exactly these two emails by exact match; aborts if anything else matches.
// Does not touch any other account or data.
//
// Usage (from the project root, with your production env loaded):
//   node --env-file=.env.production scripts/cleanup-qa-phase3-appreciation-students.mjs

import { createClient } from "@libsql/client";

const TARGET_EMAILS = ["qa.eleve.phase3.7eaf@cciga.test", "qa.eleve.phase3.petite@cciga.test"];

const url = process.env.DATABASE_URL;
if (!url) {
  console.error("DATABASE_URL is not set. Load your .env.production first (--env-file=.env.production).");
  process.exit(1);
}

const client = createClient({ url, authToken: process.env.TURSO_AUTH_TOKEN });

const users = await client.execute({
  sql: `SELECT id, email, name, roles FROM User WHERE email IN (${TARGET_EMAILS.map(() => "?").join(",")})`,
  args: TARGET_EMAILS,
});

if (users.rows.length !== TARGET_EMAILS.length) {
  console.error(
    `Expected exactly ${TARGET_EMAILS.length} accounts, found ${users.rows.length}. Aborting — nothing changed.`,
  );
  console.error(JSON.stringify(users.rows, null, 2));
  client.close();
  process.exit(1);
}

for (const row of users.rows) {
  const roles = JSON.parse(row.roles);
  if (!roles.every((r) => r === "STUDENT") || !row.email.startsWith("qa.eleve.phase3.")) {
    console.error(`Refusing to delete unexpected account shape: ${JSON.stringify(row)}`);
    client.close();
    process.exit(1);
  }
}

console.log("Comptes cibles confirmés :");
console.log(JSON.stringify(users.rows, null, 2));

const studentIds = users.rows.map((r) => r.id);
const placeholders = studentIds.map(() => "?").join(",");

const appreciations = await client.execute({
  sql: `SELECT id, studentId FROM StudentAppreciation WHERE studentId IN (${placeholders})`,
  args: studentIds,
});
const appreciationIds = appreciations.rows.map((r) => r.id);

const statements = [];

if (appreciationIds.length > 0) {
  const apPlaceholders = appreciationIds.map(() => "?").join(",");
  statements.push({
    sql: `DELETE FROM AuditLog WHERE entityType = 'StudentAppreciation' AND entityId IN (${apPlaceholders})`,
    args: appreciationIds,
  });
  statements.push({
    sql: `DELETE FROM StudentAppreciation WHERE id IN (${apPlaceholders})`,
    args: appreciationIds,
  });
}

statements.push({ sql: `DELETE FROM Notification WHERE userId IN (${placeholders})`, args: studentIds });
statements.push({ sql: `DELETE FROM User WHERE id IN (${placeholders})`, args: studentIds });

await client.batch(statements, "write");

console.log(`\nSupprimé : ${studentIds.length} compte(s) élève QA, ${appreciationIds.length} appréciation(s) associée(s), notifications et journaux d'audit liés.`);

client.close();
